(function(){'use strict';fetch('/api/colleges/status',{credentials:'same-origin',cache:'no-store',redirect:'error'}).then(r=>r.ok?r.json():null).then(data=>{if(!data?.user||!(data.isAdmin||data.memberships?.some(m=>m.organizationStatus==='verified')))return;const target=document.querySelector('main');if(!target)return;const p=document.createElement('p'),link=document.createElement('a');link.href='admin.html';link.textContent=data.isAdmin?'Open management workspace →':'Open college workspace →';link.style.cssText='display:inline-flex;align-items:center;min-height:48px;padding:10px 16px;border:1px solid #b7c7df;border-radius:9px;color:#204da8;font-size:16px;font-weight:650';p.append(link);target.append(p);}).catch(()=>{});}());
